window.docContents[236].resolve({"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Tensor-product-over-a-ring/#Chapter2___Remark2___11___4":{"contents":"Remark 2.11.4. Note that a similar definition to the above can be used to define the tensor product V \\otimes_A W, where A is any ring, V is a right A-module, and W is a left A-module. Namely, V \\otimes_A W is the abelian group which is the quotient of the group V \\bullet W freely generated by formal symbols v \\otimes w, v \\in V, w \\in W, modulo the\nrelations\n\n\n(v_1 + v_2) \\otimes w - v_1 \\otimes w - v_2 \\otimes w,\n\n\nv \\otimes (w_1 + w_2) - v \\otimes w_1 - v \\otimes w_2,\n\n\nva \\otimes w - v \\otimes aw, \\quad a \\in A.\n\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.11. Tensor products\u0009Tensor product over a ring","header":"Tensor product over a ring","id":"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Tensor-product-over-a-ring/#Chapter2___Remark2___11___4"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Bijection-between-representations-of-path-algebra-and-quiver/#Chapter2___Discussion_quiver_rep_bijection___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.8. Quivers\u0009Bijection between representations of path algebra and quiver\u0009Bijection between representations of path algebra and quiver","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Bijection-between-representations-of-path-algebra-and-quiver/#Chapter2___Discussion_quiver_rep_bijection___formalization"},"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Irreducible-representations-of-dihedral-groups/#Chapter4___Problem4___12___1":{"contents":"Problem 4.12.1. Let G be the group of symmetries of a regular N-gon (it has 2N elements).\n\n(a) Describe all irreducible complex representations of this group (consider the cases of odd and even N).\n\n(b) Let V be the 2-dimensional complex representation of G obtained by complexification of the standard representation on the real plane (the plane of the polygon). Find the decomposition of V \\otimes V in a direct sum of irreducible representations.\n\n\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.12. Problems\u0009Irreducible representations of dihedral groups","header":"Irreducible representations of dihedral groups","id":"/4___-Representations-of-finite-groups___-Basic-results/4___12___-Problems/Irreducible-representations-of-dihedral-groups/#Chapter4___Problem4___12___1"},"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Computing-characters-of-L_lambda-via-Schur-Weyl-duality/#Chapter5___Discussion_computing_characters_of_L_lambda":{"contents":"Proposition 5.21.1 allows us to calculate the characters of the representations L_\\lambda.\n\nNamely, let \\dim V = N, let g \\in GL(V), and let x_1, \\ldots, x_N be the eigenvalues of g on V. To compute the character \\chi_{L_\\lambda}(g) as a function of x_1, \\ldots, x_N, let us calculate \\operatorname{Tr}_{V^{\\otimes n}}(g^{\\otimes n} s), where s \\in S_n. If s \\in C_\\mathbf{i}, we easily get that this trace equals\n\n\\prod_m \\operatorname{Tr}(g^m)^{i_m} = \\prod_m H_m(x)^{i_m}.\n\nOn the other hand, by the Schur-Weyl duality\n\n\\operatorname{Tr}_{V^{\\otimes n}}(g^{\\otimes n} s) = \\sum_\\lambda \\chi_\\lambda(C_\\mathbf{i}) \\operatorname{Tr}_{L_\\lambda}(g).\n\nComparing this to Proposition 5.21.1 and using linear independence of columns of the character table of S_n, we obtain\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.22. The characters of $L_\\lambda$\u0009Computing characters of L_lambda via Schur-Weyl duality","header":"Computing characters of L_lambda via Schur-Weyl duality","id":"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Computing-characters-of-L_lambda-via-Schur-Weyl-duality/#Chapter5___Discussion_computing_characters_of_L_lambda"},"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Computing-characters-of-L_lambda-via-Schur-Weyl-duality/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___22___-The-characters-of-___L____lambda___--Computing-characters-of-L_lambda-via-Schur-Weyl-duality--Computing-characters-of-L_lambda-via-Schur-Weyl-duality--Formalization--Primary-declarations":{"contents":"A weakly decreasing weight tuple gives a representation whose weight character is the associated symmetric polynomial.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Discussion_computing_characters_of_L_lambda; role=primary]\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.22. The characters of $L_\\lambda$\u0009Computing characters of L_lambda via Schur-Weyl duality\u0009Computing characters of L_lambda via Schur-Weyl duality\u0009Formalization","header":"Primary declarations","id":"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Computing-characters-of-L_lambda-via-Schur-Weyl-duality/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___22___-The-characters-of-___L____lambda___--Computing-characters-of-L_lambda-via-Schur-Weyl-duality--Computing-characters-of-L_lambda-via-Schur-Weyl-duality--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/L____lambda___1___N___-___-L_lambda-___-______N-V/#Chapter5___Proposition5___22___2___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.22. The characters of $L_\\lambda$\u0009L_{lambda+1^N} ≅ L_lambda ⊗ Λ^N V\u0009L_{lambda+1^N} ≅ L_lambda ⊗ Λ^N V","header":"Formalization","id":"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/L____lambda___1___N___-___-L_lambda-___-______N-V/#Chapter5___Proposition5___22___2___formalization"},"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Projective-dimension/#Chapter9___Definition9___4___1___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.4. Homological dimension\u0009Projective dimension\u0009Projective dimension","header":"Formalization","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Projective-dimension/#Chapter9___Definition9___4___1___formalization"}});